// Whole neighborhoods only; allow repeats. Subset J of ports is blue to the core outside its union.
use std::io::{self,BufRead};type A=[u32;27];
fn maximal(a:&A,mut p:u32,mut x:u32,s:u32,out:&mut Vec<u32>){if p|x==0{out.push(s);return}let pivot=(p|x).trailing_zeros() as usize;let mut w=p&!a[pivot];while w!=0{let b=w&w.wrapping_neg();w^=b;let i=b.trailing_zeros() as usize;maximal(a,p&a[i],x&a[i],s|b,out);p^=b;x|=b}}
fn clique(a:&A,mut p:u32,k:u32)->bool{if k==0{return true}while p.count_ones()>=k{let b=p&p.wrapping_neg();p^=b;if clique(a,p&a[b.trailing_zeros() as usize],k-1){return true}}false}
fn choose(a:&A,rows:&[u32],compat:&[Vec<bool>],opts:&[usize],subs:&[(u32,u32)],picked:&mut Vec<usize>,goal:usize)->bool{for (pos,&i) in opts.iter().enumerate(){let s=rows[i];if subs.iter().any(|&(p,n)|n>=2&&clique(a,p&!s,8-n)){continue}picked.push(i);if picked.len()==goal{return true}let next:Vec<_>=opts[pos..].iter().copied().filter(|&j|compat[i][j]).collect();if !next.is_empty(){let mut ext=subs.to_vec();ext.extend(subs.iter().map(|&(p,n)|(p&!s,n+1)));if choose(a,rows,compat,&next,&ext,picked,goal){return true}}picked.pop();}false}
fn main(){let goal:usize=std::env::args().nth(1).map(|x|x.parse().unwrap()).unwrap_or(6);assert!(goal==6||goal==7);for l in io::stdin().lock().lines(){let l=l.unwrap();let (id,g)=l.split_once(' ').unwrap();let b=g.as_bytes();let mut a=[0;27];let mut k=0;for j in 0..27{for i in 0..j{if (b[1+k/6]-63)>>(5-k%6)&1==0{a[i]|=1<<j;a[j]|=1<<i}k+=1}}for z in 0..27{let p=((1<<27)-1)^(1<<z);let mut rows=vec![];maximal(&a,p,0,0,&mut rows);let n=rows.len();let mut c=vec![vec![false;n];n];for i in 0..n{for j in i..n{c[i][j]=!clique(&a,p&!(rows[i]|rows[j]),7)}}let mut picked=vec![];if choose(&a,&rows,&c,&(0..n).collect::<Vec<_>>(),&[(p,0)],&mut picked,goal){println!("{} {} {:?}",id,z,picked.iter().map(|&i|rows[i]).collect::<Vec<_>>());}else{println!("{} {} []",id,z)}}}}
